using System.Net;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.Http.Metadata;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.DependencyInjection;

namespace FeatureFlow.Api.Tests;

/// <summary>
/// The API's OpenAPI document (docs/02 section 7; G7): generated by ASP.NET Core from the routes' metadata, committed at
/// <c>src/FeatureFlow.Api/openapi.json</c> for the console's generated client (A4), and held to the routes here. Run with
/// <c>FF_WRITE_OPENAPI=1</c> to write the generated document over the committed one (LOG A3-0c); never edit it by hand.
/// </summary>
public sealed class OpenApiTests
{
    static readonly string Committed = Path.Combine(Repository.Root, "src", "FeatureFlow.Api", "openapi.json");

    /// <summary>The document as the API serves it, unauthenticated, with the routes it was generated from.</summary>
    internal static async Task<(JsonObject Document, IReadOnlyList<RouteEndpoint> Routes)> GeneratedAsync()
    {
        await using var world = new ApiWorld();
        using var anonymous = new HttpClient { BaseAddress = world.Address };
        using var response = await anonymous.GetAsync("openapi.json", TestContext.Current.CancellationToken);
        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        var document = JsonNode.Parse(await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken))!.AsObject();
        var routes = world.Services.GetRequiredService<EndpointDataSource>().Endpoints.OfType<RouteEndpoint>()
            .Where(e => e.Metadata.GetMetadata<IExcludeFromDescriptionMetadata>() is not { ExcludeFromDescription: true }).ToList();
        return (document, routes);
    }

    static string Normalised(JsonNode document) => document.ToJsonString(new JsonSerializerOptions { WriteIndented = true }).ReplaceLineEndings("\n") + "\n";

    [Fact]
    public async Task The_committed_document_is_the_generated_one()
    {
        var generated = Normalised((await GeneratedAsync()).Document);
        if (Environment.GetEnvironmentVariable("FF_WRITE_OPENAPI") == "1")
        {
            await File.WriteAllTextAsync(Committed, generated, TestContext.Current.CancellationToken);
            return;
        }

        Assert.True(File.Exists(Committed), $"{Committed} is missing: run this test with FF_WRITE_OPENAPI=1 to write it");
        var committed = Normalised(JsonNode.Parse(await File.ReadAllTextAsync(Committed, TestContext.Current.CancellationToken))!);
        Assert.True(committed == generated,
            "src/FeatureFlow.Api/openapi.json is not the document the API generates: run this test with FF_WRITE_OPENAPI=1 to regenerate it, never edit it by hand");
    }

    /// <summary>
    /// Every mapped route not excluded from the description (inbound and console routes are) is in the document with its
    /// method and path, an operation id, a success response with a schema, its refusals, and for a POST its JSON body; and
    /// every operation in the document is a mapped route.
    /// </summary>
    [Fact]
    public async Task Every_route_is_described_and_every_description_is_routed()
    {
        var (document, routes) = await GeneratedAsync();

        var routed = routes.SelectMany(r => r.Metadata.GetMetadata<IHttpMethodMetadata>()!.HttpMethods.Select(m => $"{m} /{r.RoutePattern.RawText!.TrimStart('/')}"))
            .Order(StringComparer.Ordinal).ToList();
        var operations = document["paths"]!.AsObject()
            .SelectMany(path => path.Value!.AsObject().Select(op => (Key: $"{op.Key.ToUpperInvariant()} {path.Key}", Operation: op.Value!.AsObject()))).ToList();
        Assert.Equal(routed, operations.Select(o => o.Key).Order(StringComparer.Ordinal));

        var problems = new List<string>();
        foreach (var (key, operation) in operations)
        {
            if (operation["operationId"]?.GetValue<string>() is not { Length: > 0 })
                problems.Add($"{key}: no operation id (.WithName)");
            var responses = operation["responses"]?.AsObject() ?? [];
            if (!responses.Any(r => r.Key.StartsWith('2') && r.Value?["content"]?.AsObject().Any(media => media.Value?["schema"] is not null) == true))
                problems.Add($"{key}: no success response with a schema (.Produces)");
            if (!responses.Any(r => r.Key == "401"))
                problems.Add($"{key}: no 401 refusal");
            if (key.StartsWith("POST ", StringComparison.Ordinal) && operation["requestBody"]?["content"]?["application/json"]?["schema"] is null)
                problems.Add($"{key}: no JSON request body (.Taking)");
        }

        Assert.True(problems.Count == 0, string.Join("\n", problems));
    }

    /// <summary>
    /// The document names the bearer token as an HTTP security scheme and requires it of every operation it describes, so a
    /// generated client sends it; the document itself is read without one (<see cref="GeneratedAsync"/> reads it anonymously).
    /// </summary>
    [Fact]
    public async Task Every_described_operation_takes_the_bearer_token()
    {
        var (document, _) = await GeneratedAsync();

        var scheme = document["components"]?["securitySchemes"]?["bearer"]?.AsObject();
        Assert.Equal(("http", "bearer"), (scheme?["type"]?.GetValue<string>(), scheme?["scheme"]?.GetValue<string>()));
        var required = Assert.Single(document["security"]!.AsArray())!.AsObject();
        Assert.Equal(["bearer"], required.Select(r => r.Key));
        var overridden = document["paths"]!.AsObject().SelectMany(path => path.Value!.AsObject().Where(op => op.Value!["security"] is not null).Select(op => $"{op.Key} {path.Key}"));
        Assert.Empty(overridden);
    }

    [Fact]
    public async Task No_schema_has_an_untyped_property()
    {
        var (document, _) = await GeneratedAsync();

        var untyped = new List<string>();
        foreach (var (name, schema) in document["components"]!["schemas"]!.AsObject())
            Walk(schema!, $"#/components/schemas/{name}");
        Assert.True(untyped.Count == 0, "untyped schemas (an object or JsonNode in a record): " + string.Join(", ", untyped));

        void Walk(JsonNode schema, string where)
        {
            var s = schema.AsObject();
            if (!s.ContainsKey("type") && !s.ContainsKey("$ref") && !s.ContainsKey("enum") && !s.ContainsKey("oneOf") && !s.ContainsKey("anyOf") && !s.ContainsKey("allOf"))
                untyped.Add(where);
            foreach (var (property, inner) in s["properties"]?.AsObject() ?? [])
                Walk(inner!, $"{where}/properties/{property}");
            if (s["items"] is JsonObject items)
                Walk(items, $"{where}/items");
            if (s["additionalProperties"] is JsonObject additional)
                Walk(additional, $"{where}/additionalProperties");
        }
    }
}
